```artifact
{
  "testSuite": [
    {
      "id": "U07_Alarms_FSM",
      "description": "Finite State Machine for Alarms",
      "states": [
        {
          "name": "Idle",
          "transitions": [
            {
              "event": "MediumSeverityAlarmTriggered",
              "guard": "true",
              "target": "MediumSeverityAlarmState"
            },
            {
              "event": "HighSeverityAlarmTriggered",
              "guard": "true",
              "target": "HighSeverityAlarmState"
            },
            {
              "event": "ApneaAlarmTriggered",
              "guard": "true",
              "target": "ApneaAlarmState"
            },
            {
              "event": "BreathRateAlarmTriggered",
              "guard": "true",
              "target": "BreathRateAlarmState"
            },
            {
              "event": "PressureLowAlarmTriggered",
              "guard": "true",
              "target": "PressureLowAlarmState"
            }
          ]
        },
        {
          "name": "MediumSeverityAlarmState",
          "transitions": [
            {
              "event": "PauseAlarm",
              "guard": "true",
              "target": "Idle"
            }
          ]
        },
        {
          "name": "HighSeverityAlarmState",
          "transitions": [
            {
              "event": "PauseAlarm",
              "guard": "true",
              "target": "Idle"
            }
          ]
        },
        {
          "name": "ApneaAlarmState",
          "transitions": [
            {
              "event": "PauseAlarm",
              "guard": "true",
              "target": "Idle"
            }
          ]
        },
        {
          "name": "BreathRateAlarmState",
          "transitions": [
            {
              "event": "PauseAlarm",
              "guard": "true",
              "target": "Idle"
            }
          ]
        },
        {
          "name": "PressureLowAlarmState",
          "transitions": [
            {
              "event": "PauseAlarm",
              "guard": "true",
              "target": "Idle"
            }
          ]
        }
      ]
    }
  ],
  "testCases": [
    {
      "id": "TC-001",
      "title": "Medium Severity Alarm Indication",
      "req_ids": ["RW-SW-75"],
      "kind": "positive",
      "preconditions": ["Alarm system is idle"],
      "inputs": {"name": "AlarmTrigger"},
      "steps": ["Trigger medium severity alarm"],
      "expected": ["Alarm is indicated with yellow color and flashing frequency of 0.5Hz"]
    },
    {
      "id": "TC-002",
      "title": "High Severity Alarm Indication",
      "req_ids": ["RW-SW-76", "RW-SW-77"],
      "kind": "positive",
      "preconditions": ["Alarm system is idle"],
      "inputs": {"name": "AlarmTrigger"},
      "steps": ["Trigger high severity alarm"],
      "expected": ["Alarm is indicated with auditory signal of 10 pulses, each lasting 200ms with a pulse frequency of 500Hz"]
    },
    {
      "id": "TC-003",
      "title": "Alarm Pause",
      "req_ids": ["RW-SW-78"],
      "kind": "positive",
      "preconditions": ["All active alarms are triggered"],
      "inputs": {"name": "PressAudioPauseAlarm"},
      "steps": ["Press Audio Pause Alarm"],
      "expected": ["All active alarms are paused for 60 seconds"]
    },
    {
      "id": "TC-004",
      "title": "Apnea Alarm Indication",
      "req_ids": ["RW-SW-80"],
      "kind": "positive",
      "preconditions": ["No breath is triggered within apnea time interval"],
      "inputs": {"name": "ApneaAlarmTrigger"},
      "steps": ["Trigger apnea alarm"],
      "expected": ["Ventilator responds with medium priority alarm with display text 'APNEA ALARM'"]
    },
    {
      "id": "TC-005",
      "title": "Breath Rate Alarm Indication",
      "req_ids": ["RW-SW-82"],
      "kind": "positive",
      "preconditions": ["Breath rate exceeds setting"],
      "inputs": {"name": "BreathRateAlarmTrigger"},
      "steps": ["Trigger breath rate alarm"],
      "expected": ["Device triggers medium level alarm with display text 'HIGH BREATH RATE'"]
    },
    {
      "id": "TC-006",
      "title": "Pressure Low Alarm Indication",
      "req_ids": ["RW-SW-84"],
      "kind": "positive",
      "preconditions": ["Pressure is low"],
      "inputs": {"name": "PressureLowAlarmTrigger"},
      "steps": ["Trigger pressure low alarm"],
      "expected": ["GUI sounds and displays high severity alarm with text 'LOW INSP P'"]
    }
  ]
}
